const INF=1e15;
function parseEntry(s,type){s=String(s==null?"":s).trim();if(s===""||s==="-")return{any:true};
 if(type==="num"){const iv=[];for(const part of s.split(/,(?![^\[\(]*[\]\)])/)){const p=part.trim();let m;
   if(m=p.match(/^([\[\(])\s*(-?[\d.]+)\s*\.\.\s*(-?[\d.]+)\s*([\]\)])$/))iv.push({lo:+m[2],hi:+m[3],li:m[1]==="[",hi_i:m[4]==="]"});
   else if(m=p.match(/^(<=|>=|<|>|=)\s*(-?[\d.]+)$/)){const v=+m[2],o=m[1];iv.push(o==="<="?{lo:-INF,hi:v,li:true,hi_i:true}:o==="<"?{lo:-INF,hi:v,li:true,hi_i:false}:o===">="?{lo:v,hi:INF,li:true,hi_i:true}:o===">"?{lo:v,hi:INF,li:false,hi_i:true}:{lo:v,hi:v,li:true,hi_i:true})}
   else if(/^-?[\d.]+$/.test(p))iv.push({lo:+p,hi:+p,li:true,hi_i:true});else return{err:"Cannot read “"+p+"”. Try > 50000, [10..20] or a number."}}
  return{num:iv}}
 let neg=false,b=s;const m=s.match(/^not\((.*)\)$/i);if(m){neg=true;b=m[1]}
 const set=b.split(",").map(x=>x.trim().replace(/^["']|["']$/g,"").toLowerCase()).filter(Boolean);return set.length?{set,neg}:{err:"Empty list"}}
function entryMatch(d,v,type){if(d.any)return true;if(d.err)return false;if(d.num){const n=+v;if(v===""||isNaN(n))return false;return d.num.some(i=>(n>i.lo||(i.li&&n===i.lo))&&(n<i.hi||(i.hi_i&&n===i.hi)))}const has=d.set.includes(String(v).toLowerCase());return d.neg?!has:has}
const rowDesc=(t,r)=>r.c.map((c,i)=>parseEntry(c,t.inputs[i].t));
function rowMatch(t,ds,vals){return ds.every((d,i)=>entryMatch(d,vals[i],t.inputs[i].t))}
function samples(t,ds){const per=t.inputs.map((inp,i)=>{if(inp.t==="txt")return(inp.o||[]).slice();const bs=new Set([0]);ds.forEach(r=>r[i].num&&r[i].num.forEach(v=>{[v.lo,v.hi].forEach(b=>{if(Math.abs(b)<INF/2){bs.add(b-.5);bs.add(b);bs.add(b+.5)}})}));return[...bs].sort((a,b)=>a-b)});
 let combos=[[]];per.forEach(p=>{const n=[];combos.forEach(cb=>p.forEach(v=>{if(n.length<4000)n.push(cb.concat([v]))}));combos=n});return combos}
function analyze(t){const ds=t.rows.map(r=>rowDesc(t,r)),out={bad:[],ov:[],shadow:[],gaps:[]};
 ds.forEach((r,ri)=>r.forEach((d,ci)=>{if(d.err)out.bad.push(`Row ${ri+1}, ${t.inputs[ci].l}: ${d.err}`)}));
 if(out.bad.length)return out;
 const hits=t.rows.map(()=>0),seen={};
 samples(t,ds).forEach(v=>{const m=[];ds.forEach((r,i)=>{if(rowMatch(t,r,v))m.push(i)});if(!m.length){if(out.gaps.length<3)out.gaps.push(v)}else{hits[m[0]]++;if(m.length>1){const k=m.slice(0,2).join(",");if(!seen[k]){seen[k]={a:m[0],b:m[1],ex:v};out.ov.push(seen[k])}}}});
 if(t.hp==="first")hits.forEach((h,i)=>{if(!h&&!ds[i].every(d=>d.any&&false))out.shadow.push(i)});
 t.rows.forEach((r,i)=>{r._hit=hits[i]});return out}
const exTxt=(t,v)=>t.inputs.map((inp,i)=>`${inp.l.toLowerCase()} ${inp.t==="num"?(+v[i]).toLocaleString("en-US"):v[i]}`).join(", ");
function decide(t,vals){const ds=t.rows.map(r=>rowDesc(t,r));const vs=t.inputs.map(i=>vals[i.k]==null?"":vals[i.k]);const matches=[];ds.forEach((d,i)=>{if(rowMatch(t,d,vs))matches.push(i)});
 const why=(ri)=>t.inputs.map((inp,ci)=>{const e=t.rows[ri].c[ci],ok=entryMatch(ds[ri][ci],vs[ci],inp.t);return{ok,txt:`${inp.l} ${inp.t==="num"?(+vs[ci]).toLocaleString("en-US"):vs[ci]} ${ok?"satisfies":"does not satisfy"} “${e===""?"-":e}”`}});
 const why2=[];t.rows.forEach((r,ri)=>{if(!matches.includes(ri)){const f=why(ri).find(x=>!x.ok);why2.push({ri,txt:f?f.txt:"skipped"})}});
 let fired=[];let err=null;if(t.hp==="first")fired=matches.slice(0,1);else if(t.hp==="unique"){if(matches.length>1)err=`Conflict: rows ${matches.map(i=>"R"+(i+1)).join(" and ")} all match, and a unique table allows only one.`;else fired=matches}else fired=matches;
 return{matches,fired,err,why,why2,vs}}
function dmnRun(id,rec){const t=F.dmn.find(x=>x.id===id);if(!t)return null;const vals={};for(const i of t.inputs){let v=rec[i.k];if(i.k==="accepted")v=rec.accepted?"Yes":"No";if(v===undefined)return null;vals[i.k]=v}
 const d=decide(t,vals);if(!d.fired.length)return{name:t.name,rows:["none"],text:d.err||"no rule matched"};return{name:t.name,rows:d.fired.map(i=>"R"+(i+1)),text:d.fired.map(i=>t.rows[i].o.join(" / ")).join(" + ")}}
const HPX={first:["First","The first row that matches wins. Order matters, so drag rows to reorder."],unique:["Unique","Exactly one row may match. Overlapping rows are errors."],collect:["Collect","Every matching row contributes an output. Overlap is expected."]};
function dmnTest(t){const st=F.dt[t.id]=F.dt[t.id]||{vals:clone(t.sample)};return st}
function analysisHTML(t){const a=analyze(t);if(a.bad.length)return `<ul class="flw-vl">${a.bad.map(x=>`<li class="err"><span class="flw-vi">${ico("warn")}</span><div><b>${X(x)}</b></div></li>`).join("")}</ul>`;
 const items=[];
 a.ov.slice(0,t.hp==='unique'?8:3).forEach(o=>items.push({s:t.hp==="unique"?"err":"info",m:`Rows R${o.a+1} and R${o.b+1} can both match, for example ${exTxt(t,o.ex)}.`,h:t.hp==="unique"?"A unique table must not overlap. Narrow one of the rows, or switch to First if order should decide.":t.hp==="first"?`First policy: R${o.a+1} wins because it is higher. That is fine if intended.`:"Collect policy: both rows contribute an output."}));
 if(t.hp==="first")a.shadow.forEach(i=>items.push({s:"warn",m:`Row R${i+1} can never fire. Earlier rows already match every case it covers.`,h:"Delete it, or move it above the row that shadows it."}));
 a.gaps.forEach(g=>items.push({s:t.hp==="collect"?"info":"warn",m:`No row matches ${exTxt(t,g)}.`,h:t.hp==="collect"?"Nothing is added for this request, which may be intended.":"Add a catch-all row at the bottom so every case gets a decision."}));
 const n=items.filter(x=>x.s!=="info").length;
 return `<div class="row sp"><b>${n?`${n} issue${n>1?"s":""} found`:"No conflicts or gaps"}</b><span class="muted small">${t.rows.length} rows checked against ${samples(t,t.rows.map(r=>rowDesc(t,r))).length} sampled inputs</span></div>`+(items.length?`<ul class="flw-vl">${items.map(x=>`<li class="${x.s}"><span class="flw-vi">${ico(x.s==="err"?"warn":"info")}</span><div><b>${X(x.m)}</b><div class="muted small">${X(x.h)}</div></div></li>`).join("")}</ul>`:`<div class="flw-ok">${ico("check")}<span>Every sampled input matches a row, and no rows overlap.</span></div>`)}
function resultHTML(t){const st=dmnTest(t),d=decide(t,st.vals);let h="";
 if(d.err)h+=`<div class="flw-res bad"><b>${X(d.err)}</b><div class="muted small">The workflow would stop and send this to the table owner.</div></div>`;
 else if(!d.fired.length)h+=`<div class="flw-res warn"><b>No rule matches these inputs.</b><div class="muted small">Add a catch-all row so every case gets a decision.</div></div>`;
 else h+=d.fired.map(i=>`<div class="flw-res good"><div class="row sp"><b>Rule R${i+1} fires</b>${pill(t.hp==="collect"?"Collected":HPX[t.hp][0],"info")}</div><dl class="kv">${t.outputs.map((o,oi)=>`<dt>${X(o.l)}</dt><dd><b>${X(t.rows[i].o[oi]||"")}</b></dd>`).join("")}</dl><div class="eyebrow" style="margin:8px 0 4px">Why</div><ul class="flw-why">${d.why(i).map(w=>`<li class="${w.ok?"ok":"no"}">${ico(w.ok?"check":"warn")}${X(w.txt)}</li>`).join("")}</ul></div>`).join("");
 const skipped=t.hp==="first"&&d.fired.length?d.why2.filter(x=>x.ri<d.fired[0]):d.why2;
 if(skipped.length)h+=`<details class="flw-det"><summary>Why ${skipped.length} other row${skipped.length>1?"s":""} did not fire</summary><ul class="flw-why">${skipped.map(x=>`<li class="no">${ico("info")}R${x.ri+1}: ${X(x.txt)}</li>`).join("")}</ul></details>`;
 return h}
function dmnPaint(t){$$(`[data-flw-drow]`).forEach(r=>{const idx=+r.dataset.flwDrow;const d=decide(t,dmnTest(t).vals);r.classList.toggle("hit",d.fired.includes(idx));r.classList.toggle("hit-soft",d.matches.includes(idx)&&!d.fired.includes(idx))});const r=$q("#flwDres");if(r)r.innerHTML=resultHTML(t);const a=$q("#flwDan");if(a)a.innerHTML=analysisHTML(t)}
function dmnGrid(t){const nI=t.inputs.length,nO=t.outputs.length,cols=`26px 34px ${"minmax(112px,1fr) ".repeat(nI)}${"minmax(124px,1.2fr) ".repeat(nO)}34px`;const d=decide(t,dmnTest(t).vals);
 return `<div class="flw-dwrap"><div class="flw-dgrid"><div class="flw-dhead" style="--cols:${cols}"><span></span><span>#</span>${t.inputs.map(i=>`<span class="in" title="Input">${X(i.l)}<small>${i.t==="num"?"number":"text"}</small></span>`).join("")}${t.outputs.map(o=>`<span class="out" title="Output">${X(o.l)}<small>output</small></span>`).join("")}<span></span></div>
  <div data-dnd="${t.id}" data-dnd-scope="flw_dmn" class="flw-dbody">${t.rows.map((r,ri)=>`<div class="flw-drow${d.fired.includes(ri)?" hit":""}${d.matches.includes(ri)&&!d.fired.includes(ri)?" hit-soft":""}" style="--cols:${cols}" data-flw-drow="${ri}" data-dnd-id="${r.id}" tabindex="0" aria-label="Rule ${ri+1}. Alt plus arrow keys to reorder."><span class="g">${grip}</span><span class="n">${r.ai?`<i class="flw-aib" title="Suggested by AI, not yet edited">${ico("sparkle")}</i>`:"R"+(ri+1)}</span>${r.c.map((c,ci)=>`<input class="flw-cell${parseEntry(c,t.inputs[ci].t).err?" bad":""}" data-flw-cell="${t.id}|${ri}|c|${ci}" value="${X(c)}" aria-label="Rule ${ri+1}, ${X(t.inputs[ci].l)}" title="${X(t.inputs[ci].t==="num"?"Examples: > 50000, [10..20], 5, -":"Examples: Low,Medium · not(High) · - for any")}">`).join("")}${r.o.map((c,ci)=>`<input class="flw-cell out" data-flw-cell="${t.id}|${ri}|o|${ci}" value="${X(c)}" aria-label="Rule ${ri+1}, ${X(t.outputs[ci].l)}">`).join("")}<button class="flw-x" data-flw-delrow="${t.id}|${ri}" aria-label="Remove rule ${ri+1}" title="Remove rule">${IC("M6 6l12 12M18 6L6 18")}</button></div>`).join("")}</div></div></div>`}
function testerHTML(t){const st=dmnTest(t);return `<div class="fgrid flw-tgrid">${t.inputs.map(i=>`<div class="fld"><label class="flab" for="flwt_${i.k}">${X(i.l)}</label>${i.t==="num"?`<input class="fin" type="number" id="flwt_${i.k}" data-flw-tin="${t.id}|${i.k}" value="${X(st.vals[i.k]==null?"":st.vals[i.k])}">`:`<select class="fin" id="flwt_${i.k}" data-flw-tin="${t.id}|${i.k}">${i.o.map(o=>`<option ${o===st.vals[i.k]?"selected":""}>${X(o)}</option>`).join("")}</select>`}</div>`).join("")}</div><div id="flwDres" class="flw-resbox">${resultHTML(t)}</div>`}
function dmnBody(t){return `<div data-flw-dmnroot>
 <section class="card glass"><div class="cardhead"><div><h3>${X(t.name)}</h3><span class="muted small" data-role="story">${X(t.desc)}</span></div><div class="row"><button class="btn" data-flw-addrow="${t.id}">Add rule</button>${t.ai?`<button class="btn" data-flw-airow="${t.id}">${ico("sparkle")}Suggest a rule</button>`:""}</div></div>
  <div class="row" style="margin-bottom:12px"><span class="eyebrow" style="margin:0">Hit policy</span>${Object.keys(HPX).map(k=>`<button class="chip" data-flw-hp="${t.id}|${k}" aria-pressed="${t.hp===k}">${HPX[k][0]}</button>`).join("")}<span class="muted small">${HPX[t.hp][1]}</span></div>
  ${dmnGrid(t)}<p class="muted small" style="margin:10px 0 0">Click any cell to edit. Number columns accept <code>&gt; 50000</code>, <code>[10..20]</code> or <code>-</code> for any. Text columns accept <code>Low,Medium</code> or <code>not(High)</code>. Drag the grip to reorder.</p></section>
 <div class="grid g2"><section class="card glass"><div class="cardhead"><div><h3>Conflicts and gaps</h3><span class="muted small" data-role="story">Checked live as you edit.</span></div></div><div id="flwDan">${analysisHTML(t)}</div></section>
 <section class="card glass"><div class="cardhead"><div><h3>Tester</h3><span class="muted small" data-role="story">Enter an input and see which rule fires and why. The matched row lights up above.</span></div></div>${testerHTML(t)}</section></div></div>`}
REG("flw_dmn","Decision tables","automate","M4 5h16v14H4zM4 10h16M10 5v14",()=>{const rows=F.dmn.reduce((s,t)=>s+t.rows.length,0),issues=F.dmn.reduce((s,t)=>{const a=analyze(t);return s+(t.hp==="unique"?a.ov.length:0)+(t.hp==="first"?a.shadow.length:0)+(t.hp==="collect"?0:a.gaps.length)+a.bad.length},0);const t=dmnOf(F.dsel);
 return `<div class="screen">${hero("Automation · Decision tables",`Write the rule once, see it decide`,`<b>${F.dmn.length} tables</b> hold <b>${rows} rules</b> that route invoices, changes, tickets and catalog requests. Today <b>41%</b> of approvals clear by rule alone. ${issues?`<b>${issues} issue${issues>1?"s":""}</b> need a look.`:"No overlaps or gaps."}`,`<div class="row">${fchip("m_autoapp")}${aiChip({model:"Claude Sonnet",conf:.84,title:"Rule suggestions",note:"Suggested rows come from approver overrides over the last 90 days. You decide whether to keep them.",src:["Approver overrides, 90 days","Invoice history"]})}</div>`)}${lensNote()}
 <div class="row">${F.dmn.map(x=>`<button class="chip" data-flw-dsel="${x.id}" aria-pressed="${x.id===t.id}">${X(x.name)}</button>`).join("")}</div>${dmnBody(t)}</div>`});
DND.on("flw_dmn",(id,from,to,idx)=>{const t=dmnOf(from),i=t.rows.findIndex(r=>r.id===id);if(i<0)return;const[r]=t.rows.splice(i,1);t.rows.splice(Math.max(0,Math.min(idx,t.rows.length)),0,r);r.ai=false;toast("Moved to position "+(t.rows.indexOf(r)+1)+(t.hp==="first"?". Order changes which rule wins.":"."),"info");render()});
document.addEventListener("click",e=>{const t=e.target.closest("[data-flw-dsel],[data-flw-hp],[data-flw-addrow],[data-flw-airow],[data-flw-delrow]");if(!t)return;const d=t.dataset;
 if(d.flwDsel){F.dsel=d.flwDsel;render();return}
 if(d.flwHp){const[id,k]=d.flwHp.split("|"),tb=dmnOf(id);tb.hp=k;audit("changed hit policy",tb.name+" → "+k);toast("Hit policy: "+HPX[k][0]+". Conflicts re-checked.","info");render();return}
 if(d.flwAddrow){const tb=dmnOf(d.flwAddrow);tb.rows.push({id:tb.id+"_r"+uid(),c:tb.inputs.map(()=>"-"),o:tb.outputs.map(()=>"")});audit("added rule",tb.name);toast("Blank rule added at the bottom. It matches everything until you narrow it.","info");render();return}
 if(d.flwAirow){const tb=dmnOf(d.flwAirow);if(tb.rows.some(r=>r.ai)){toast("Review the suggested rule first.","warn");return}tb.rows.unshift({id:tb.id+"_r"+uid(),c:tb.ai.c.slice(),o:tb.ai.o.slice(),ai:true});audit("accepted AI suggestion","rule for "+tb.name);toast("Suggested: "+tb.ai.why,"info");render();return}
 if(d.flwDelrow){const[id,ri]=d.flwDelrow.split("|"),tb=dmnOf(id);const r=tb.rows.splice(+ri,1)[0];audit("removed rule",tb.name+" R"+(+ri+1));toast("Rule R"+(+ri+1)+" removed.","warn");render()}});
document.addEventListener("input",e=>{const c=e.target.closest&&e.target.closest("[data-flw-cell]");if(c){const[id,ri,k,ci]=c.dataset.flwCell.split("|"),tb=dmnOf(id),r=tb.rows[+ri];if(!r)return;r[k==="c"?"c":"o"][+ci]=c.value;r.ai=false;if(k==="c")c.classList.toggle("bad",!!parseEntry(c.value,tb.inputs[+ci].t).err);dmnPaint(tb);return}
 const ti=e.target.closest&&e.target.closest("[data-flw-tin]");if(ti){const[id,k]=ti.dataset.flwTin.split("|"),tb=dmnOf(id);dmnTest(tb).vals[k]=ti.type==="number"?(ti.value===""?"":+ti.value):ti.value;dmnPaint(tb)}});
document.addEventListener("change",e=>{const c=e.target.closest&&e.target.closest("[data-flw-cell]");if(c){const[id,ri]=c.dataset.flwCell.split("|"),tb=dmnOf(id);audit("edited rule cell",tb.name+" R"+(+ri+1)+": "+c.value);const ti=e.target.closest("[data-flw-tin]");}
 const ti=e.target.closest&&e.target.closest("[data-flw-tin]");if(ti){const[id,k]=ti.dataset.flwTin.split("|"),tb=dmnOf(id);dmnTest(tb).vals[k]=ti.value;dmnPaint(tb)}});

