function stepHTML(w,s,i){const kind=s.tools.length?s.tools.map(t=>TSC[t]).includes("write")?"write":"read":"think";return `<div class="flw-step" data-dnd-id="${s.id}" tabindex="0" aria-label="Step ${i+1}: ${X(s.n)}. Alt plus arrow keys to reorder."><span class="g">${grip}</span><span class="flw-sn num">${i+1}</span><div class="flw-sm"><b>${X(s.n)}</b><div class="row" style="gap:6px;margin-top:4px">${s.tools.length?s.tools.map(t=>`<span class="pill ${TSC[t]==="write"?"warn":"mute"}" title="${TSC[t]} access">${IC("M7 11V8a5 5 0 0 1 10 0v3M6 11h12v9H6z").replace('width="21" height="21"','width="12" height="12"')}${X(t)}</span>`).join(""):'<span class="muted small">No tools: reasoning only</span>'}<button class="chip" data-flw-stedit="${w.id}|${s.id}" style="padding:2px 10px;font-size:12px">Tools and name</button></div></div><div class="flw-au" role="radiogroup" aria-label="Human in the loop for step ${i+1}">${AUL.map(a=>`<button class="chip" role="radio" aria-checked="${s.au===a[0]}" aria-pressed="${s.au===a[0]}" data-flw-au="${w.id}|${s.id}|${a[0]}">${a[1]}</button>`).join("")}</div></div>`}
function wfDetail(w){const[sl,sc]=wfStat(w),ok=w.runs.filter(r=>r.st==="completed").length,wk=w.runs.reduce((s,r)=>s+runCost(r),0),tk=w.runs.reduce((s,r)=>s+r.tin+r.tout,0);
 return `<section class="card glass"><div class="cardhead"><div><h3>${X(w.name)}</h3><span class="muted small" data-role="story">${X(w.goal)}</span></div><div class="row">${pill(sl,sc)}${aiChip({model:(AGENTS.find(a=>a.n===w.agent)||{}).model||"Claude",conf:.88,title:w.agent+" in this workflow",note:"Runs inside the AI gateway: every tool call is checked against the permissions below and logged.",src:["Step permissions","Guardrail settings","Agent registry"],guards:["Stops at the spend cap","Writes need approval when the guardrail is on","Kill switch overrides everything"]})}<button class="btn" data-flw-guard="${w.id}">Guardrails</button></div></div>
 ${w.kill?`<div class="hint" style="display:block;background:var(--bad-s);color:var(--bad);margin-bottom:12px"><b>Kill switch level ${w.kill} is on.</b> ${X(KILL[w.kill-1][1])} ${w.killReason?"Reason: "+X(w.killReason)+".":""} <button class="chip" data-flw-restore-wf="${w.id}">Restore workflow</button></div>`:""}
 <div class="grid g4"><div class="flw-mini2 glass"><span class="muted small">Runs, last 7 days</span><b class="num" data-role="metric" style="font-size:26px">${w.runs.length}</b></div><div class="flw-mini2 glass"><span class="muted small">Success</span><b class="num" data-role="metric" style="font-size:26px">${Math.round(ok/w.runs.length*100)}%</b></div><div class="flw-mini2 glass"><span class="muted small">Tokens</span><b class="num" data-role="metric" style="font-size:26px">${(tk/1000).toFixed(0)}K</b></div><div class="flw-mini2 glass"><span class="muted small">Cost</span><b class="num" data-role="metric" style="font-size:26px">$${wk.toFixed(2)}</b></div></div></section>
 <div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>Steps and human-in-the-loop policy</h3><span class="muted small" data-role="story">Set how much freedom each step has. Drag to reorder. Writes to money or access should ask first.</span></div><button class="btn" data-flw-stadd="${w.id}">Add step</button></div>
  <div class="flw-steps" data-dnd="${w.id}" data-dnd-scope="flw_agstep">${w.steps.map((s,i)=>stepHTML(w,s,i)).join("")}</div>
  <div class="row small muted" style="margin-top:10px"><span><b>Autonomous</b>: acts, then logs</span><span><b>Propose then approve</b>: waits for ${X(w.reviewers.join(" or "))}</span><span><b>Suggest only</b>: shows, never acts</span></div></section>
 <div class="pane"><section class="card glass"><div class="cardhead"><div><h3>Kill switch</h3><span class="muted small" data-role="story">Three levels, most gentle first. Anyone with the reviewer role can pull it.</span></div></div><div class="flw-kill">${KILL.map((k,i)=>`<button class="flw-kl l${i+1}${w.kill===i+1?" on":""}" data-flw-kill="${w.id}|${i+1}"><b>Level ${i+1}: ${k[0]}</b><span class="small muted">${k[1]}</span></button>`).join("")}</div></section>
  <section class="card glass"><div class="cardhead"><div><h3>Guardrails</h3><span class="muted small" data-role="story">Limits apply per run unless noted.</span></div></div><dl class="kv"><dt>Max steps</dt><dd class="num" data-role="metric">${w.limits.steps}</dd><dt>Spend cap per run</dt><dd class="num" data-role="metric">$${w.limits.spend.toFixed(2)}</dd><dt>Runs per day</dt><dd class="num" data-role="metric">${w.limits.perDay}</dd><dt>Money it may move</dt><dd class="num" data-role="metric">${w.limits.money?money(w.limits.money):"None"}</dd><dt>Hours</dt><dd>${X(w.limits.hours)}</dd><dt>Reviewers</dt><dd>${w.reviewers.map(X).join(", ")}</dd><dt>Protections</dt><dd><div class="row" style="gap:6px">${w.guard.pii?pill("Redact personal data","info"):""}${w.guard.cite?pill("Must cite sources","info"):""}${w.guard.writes?pill("Writes need approval","info"):""}${w.guard.ext?"":pill("No external domains","info")}${pill("Escalate under "+w.guard.conf+"% confidence","mute")}</div></dd></dl></section></div></div>
 <section class="card glass"><div class="cardhead"><div><h3>Run history</h3><span class="muted small" data-role="story">Open a run to see every step, what it cost and who approved it.</span></div>${fchip("m_wfrun")}</div><div class="tablewrap"><table class="flw-tbl"><thead><tr><th>Run</th><th>Started</th><th>Input</th><th>Status</th><th>Steps</th><th>Tokens</th><th>Cost</th><th>Time</th></tr></thead><tbody>${w.runs.map(r=>`<tr data-flw-run="${w.id}|${r.id}" tabindex="0" role="button"><td><b>${X(r.id)}</b></td><td>${X(r.at)}</td><td>${X(r.input)}</td><td>${pill(r.st==="completed"?"Completed":r.st==="awaiting"?"Awaiting approval":r.st==="failed"?"Failed":"Killed",r.st==="completed"?"good":r.st==="awaiting"?"info":"bad")}</td><td class="num">${r.trace.length}/${w.steps.length}</td><td class="num">${((r.tin+r.tout)/1000).toFixed(1)}K</td><td class="num">$${runCost(r).toFixed(3)}</td><td class="num">${X(r.dur)}</td></tr>`).join("")}</tbody></table></div></section>`}
