function planHTML(v){const P=planFor(v);return `<div class="flw-plan"><div class="row sp"><b>${ico("sparkle")} AI-drafted plan</b><span class="muted small">${P.length} steps</span></div><ol>${P.map(s=>`<li><span>${X(s.n)}</span>${pill((AUL.find(a=>a[0]===s.au)||[])[1],s.au==="autonomous"?"info":s.au==="propose"?"warn":"mute")}</li>`).join("")}</ol><p class="muted small" style="margin:6px 0 0">Plan quality improves as you pick tools. Reviewers can edit every step after creation.</p></div>`}
