 if(d.flwCtest){const c=cn(d.flwCtest);if(c.st==="failing")toast(c.n+": 401 Unauthorized. "+c.note.split(".")[0]+".","bad");else if(c.st==="paused")toast(c.n+" is paused. Resume it first.","warn");else toast(c.n+": connected in "+c.lat+" ms"+(c.st==="degraded"?", but throttled (429) at the limit.":"."),c.st==="degraded"?"warn":"good");audit("tested connection",c.n);return}
 if(d.flwCsync){const c=cn(d.flwCsync);if(c.st==="failing"){toast("Sync not started: the credential is expired. Rotate it first.","bad");return}c.last="just now";audit("synced now",c.n);toast("Sync started for "+c.n+". "+Math.round(c.calls/60)+" records queued.","good");return}
 if(d.flwCrot){rotForm(cn(d.flwCrot));return}
 if(d.flwCpause){const c=cn(d.flwCpause);c.st=c.st==="paused"?"healthy":"paused";audit(c.st==="paused"?"paused connector":"resumed connector",c.n);toast(c.n+(c.st==="paused"?" paused. Events queue until you resume.":" resumed."),"info");closeDrawer();render();return}
